import threading
import sqlite3
import hashlib
import hmac
import os
import time
from flask import Flask, request, jsonify, g
from functools import wraps

app = Flask(__name__)
app.config['SECRET_KEY'] = os.environ.get('SECRET_KEY', os.urandom(32).hex())
DB_PATH = '/tmp/app.db'

def get_db():
    if 'db' not in g:
        g.db = sqlite3.connect(DB_PATH, check_same_thread=False)
        g.db.row_factory = sqlite3.Row
        g.db.execute('PRAGMA journal_mode=WAL')
    return g.db

def init_db():
    db = sqlite3.connect(DB_PATH)
    db.execute('''CREATE TABLE IF NOT EXISTS users (
        id INTEGER PRIMARY KEY,
        username TEXT UNIQUE NOT NULL,
        password_hash TEXT NOT NULL,
        role TEXT NOT NULL DEFAULT 'viewer'
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS documents (
        id INTEGER PRIMARY KEY,
        owner_id INTEGER NOT NULL,
        title TEXT NOT NULL,
        content TEXT NOT NULL,
        classification TEXT NOT NULL DEFAULT 'public'
    )''')
    db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
        id INTEGER PRIMARY KEY,
        user_id INTEGER,
        action TEXT,
        resource_id INTEGER,
        timestamp REAL
    )''')
    db.commit()
    db.close()

def hash_password(password, salt=None):
    if salt is None:
        salt = os.urandom(16)
    dk = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return salt.hex() + ':' + dk.hex()

def verify_password(password, stored):
    salt_hex, dk_hex = stored.split(':')
    salt = bytes.fromhex(salt_hex)
    dk = hashlib.pbkdf2_hmac('sha256', password.encode(), salt, 100000)
    return hmac.compare_digest(dk.hex(), dk_hex)

def generate_token(user_id):
    timestamp = str(int(time.time()))
    payload = f"{user_id}:{timestamp}"
    sig = hmac.new(app.config['SECRET_KEY'].encode() if isinstance(app.config['SECRET_KEY'], str) else app.config['SECRET_KEY'], payload.encode(), 'sha256').hexdigest()
    return f"{payload}:{sig}"

def verify_token(token):
    try:
        parts = token.split(':')
        if len(parts) != 3:
            return None
        user_id, timestamp, sig = parts
        payload = f"{user_id}:{timestamp}"
        expected = hmac.new(app.config['SECRET_KEY'].encode() if isinstance(app.config['SECRET_KEY'], str) else app.config['SECRET_KEY'], payload.encode(), 'sha256').hexdigest()
        if not hmac.compare_digest(sig, expected):
            return None
        if int(time.time()) - int(timestamp) > 3600:
            return None
        return int(user_id)
    except (ValueError, AttributeError):
        return None

def require_auth(f):
    @wraps(f)
    def decorated(*args, **kwargs):
        token = request.headers.get('Authorization', '').replace('Bearer ', '')
        user_id = verify_token(token)
        if user_id is None:
            return jsonify({'error': 'Unauthorized'}), 401
        g.current_user_id = user_id
        return f(*args, **kwargs)
    return decorated

def get_user_role(user_id):
    """Fetch current role from database"""
    db = get_db()
    row = db.execute('SELECT role FROM users WHERE id = ?', (user_id,)).fetchone()
    if row is None:
        return None
    return row['role']

def log_access(user_id, action, resource_id):
    """Record access in audit log"""
    db = get_db()
    db.execute(
        'INSERT INTO audit_log (user_id, action, resource_id, timestamp) VALUES (?, ?, ?, ?)',
        (user_id, action, resource_id, time.time())
    )
    db.commit()

@app.route('/api/documents/<int:doc_id>/classify', methods=['POST'])
@require_auth
def classify_document(doc_id):
    """Change document classification - requires 'admin' role"""
    user_id = g.current_user_id
    new_classification = request.json.get('classification', '')

    if new_classification not in ('public', 'internal', 'confidential', 'top_secret'):
        return jsonify({'error': 'Invalid classification'}), 400

    # Step 1: Check user's current role
    role = get_user_role(user_id)
    if role != 'admin':
        return jsonify({'error': 'Forbidden: admin role required'}), 403

    # Step 2: Verify document exists
    db = get_db()
    doc = db.execute('SELECT * FROM documents WHERE id = ?', (doc_id,)).fetchone()
    if doc is None:
        return jsonify({'error': 'Document not found'}), 404

    # Step 3: Log the access attempt
    log_access(user_id, 'classify', doc_id)

    # Step 4: Perform the classification change
    db.execute(
        'UPDATE documents SET classification = ? WHERE id = ?',
        (new_classification, doc_id)
    )
    db.commit()

    return jsonify({'status': 'success', 'doc_id': doc_id, 'classification': new_classification})

@app.route('/api/documents/<int:doc_id>/content', methods=['GET'])
@require_auth
def get_document_content(doc_id):
    """Get document content - classification-based access control"""
    user_id = g.current_user_id

    # Step 1: Get user role
    role = get_user_role(user_id)

    # Step 2: Get document
    db = get_db()
    doc = db.execute('SELECT * FROM documents WHERE id = ?', (doc_id,)).fetchone()
    if doc is None:
        return jsonify({'error': 'Document not found'}), 404

    # Step 3: Check access based on role and classification
    classification = doc['classification']
    access_levels = {
        'viewer': ['public'],
        'editor': ['public', 'internal'],
        'admin': ['public', 'internal', 'confidential', 'top_secret']
    }

    allowed = access_levels.get(role, [])
    if classification not in allowed:
        return jsonify({'error': 'Access denied for your role'}), 403

    # Step 4: Log and return
    log_access(user_id, 'read', doc_id)
    return jsonify({'title': doc['title'], 'content': doc['content'], 'classification': classification})

@app.route('/api/users/<int:target_id>/role', methods=['PUT'])
@require_auth
def update_user_role(target_id):
    """Update a user's role - requires admin"""
    user_id = g.current_user_id
    new_role = request.json.get('role', '')

    if new_role not in ('viewer', 'editor', 'admin'):
        return jsonify({'error': 'Invalid role'}), 400

    # Check requester is admin
    role = get_user_role(user_id)
    if role != 'admin':
        return jsonify({'error': 'Forbidden'}), 403

    # Perform role update
    db = get_db()
    db.execute('UPDATE users SET role = ? WHERE id = ?', (new_role, target_id))
    db.commit()

    log_access(user_id, 'role_change', target_id)
    return jsonify({'status': 'success', 'user_id': target_id, 'new_role': new_role})

@app.route('/api/auth/login', methods=['POST'])
def login():
    username = request.json.get('username', '')
    password = request.json.get('password', '')

    db = get_db()
    user = db.execute('SELECT * FROM users WHERE username = ?', (username,)).fetchone()
    if user is None or not verify_password(password, user['password_hash']):
        return jsonify({'error': 'Invalid credentials'}), 401

    token = generate_token(user['id'])
    return jsonify({'token': token, 'user_id': user['id'], 'role': user['role']})

if __name__ == '__main__':
    init_db()
    app.run(threaded=True, host='0.0.0.0', port=8080)
